 const option=select.options[select.selectedIndex];const grade=option?.dataset.grade||'';
 const info={강력추천:['🟢','strong'],추천:['🔵','recommended'],보통:['🟡','normal'],비추천:['🔴','not-recommended']}[grade];
 badge.hidden=!info;badge.className='language-grade-badge'+(info?' '+info[1]:'');
