const wtadQuotes = [
  '상대가 불쾌할지 유쾌할지는 당신의 한마디에 달려 있습니다.',
  '상대의 정신을 나가게 하는 것은 압도적인 무력보다 단어 한마디가 더 효과적일 수 있습니다.',
  '큰 모욕에는 큰 책임이 필요하다.',
  '품격 있는 언어로 당신의 인격을 표현하세요.',
  '3 1 0 13 23',
  'Y O U Lo Se'
];
// 한 사이클에서 모든 문구를 한 번씩 보여준 후 다시 섞는다.
// 직전 문구와 다음 사이클의 첫 문구가 겹치지 않도록 한다.
let wtadQuoteOrder = [];
let wtadQuotePosition = 0;
let wtadLastQuote = -1;
function shuffleWtadQuotes() {
  const order = wtadQuotes.map((_, index) => index);
  for (let i = order.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  if (order.length > 1 && order[0] === wtadLastQuote) {
    const swapIndex = 1 + Math.floor(Math.random() * (order.length - 1));
    [order[0], order[swapIndex]] = [order[swapIndex], order[0]];
  }
  wtadQuoteOrder = order;
  wtadQuotePosition = 0;
}
function nextWtadQuote() {
  if (wtadQuotePosition >= wtadQuoteOrder.length) shuffleWtadQuotes();
  wtadLastQuote = wtadQuoteOrder[wtadQuotePosition++];
  return wtadQuotes[wtadLastQuote];
}
const wtadQuoteEl = document.getElementById('rotatingQuote');
if (wtadQuoteEl) {
  wtadQuoteEl.textContent = '“' + nextWtadQuote() + '”';
  setInterval(() => {
    wtadQuoteEl.classList.add('fading');
    setTimeout(() => {
      wtadQuoteEl.textContent = '“' + nextWtadQuote() + '”';
      wtadQuoteEl.classList.remove('fading');
    }, 350);
  }, 6500);
}

