function renderRaw(){const publicRawData=editionData();const race=el('raceFilter').value;const q=el('dataSearch').value.trim().toLocaleLowerCase();const selected=publicRawData.filter(r=>(race==='전체'||r.race===race)&&(!q||[r.inp,r.out,r.kind,r.source].some(v=>v.toLocaleLowerCase().includes(q))));const body=el('rawRows');body.replaceChildren();for(const r of selected){const tr=document.createElement('tr');for(const val of [r.race,r.inp,r.out,r.kind,r.status,r.source]){const td=document.createElement('td');td.textContent=val;tr.appendChild(td);}body.appendChild(tr);}el('dataCount').textContent=selected.length+'건 표시 / '+(dataEdition==='forever'?'포에버 베타':'클래식')+' 전체 '+publicRawData.length+'건';if(!selected.length){const tr=document.createElement('tr');const td=document.createElement('td');td.colSpan=6;td.textContent='현재 표시할 원본 데이터가 없습니다. 미확보 언어의 값을 임의로 채우지 않습니다.';tr.appendChild(td);body.appendChild(tr);}}
